-- -----------------------------------------------------------------------------
-- 5. Core Domain: users
-- (Altered in V20 with prompt_daily_goal; V27 with current_exam_type_id, current_level_id)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `username` VARCHAR(50) NOT NULL,
    `email` VARCHAR(190) NOT NULL,
    `password_hash` VARCHAR(255) NOT NULL,
    `full_name` VARCHAR(150) NOT NULL,
    `avatar_url` VARCHAR(500) NULL,
    `native_language_id` BIGINT NULL,
    `target_language_id` BIGINT NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    `timezone` VARCHAR(64) NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',
    `daily_goal_cards` INT NOT NULL DEFAULT 10,
    `prompt_daily_goal` BOOLEAN NOT NULL DEFAULT TRUE,
    `current_exam_type_id` BIGINT NULL,
    `current_level_id` BIGINT NULL,
    `xp_total` BIGINT NOT NULL DEFAULT 0,
    `streak_current` INT NOT NULL DEFAULT 0,
    `streak_longest` INT NOT NULL DEFAULT 0,
    `last_activity_date` DATE NULL,
    `last_active_at` DATETIME(6) NULL,
    `email_verified_at` DATETIME(6) NULL,
    `deleted_at` DATETIME(6) NULL,
    `version` BIGINT NOT NULL DEFAULT 0,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_users` PRIMARY KEY (`id`),
    CONSTRAINT `uk_users_username` UNIQUE (`username`),
    CONSTRAINT `uk_users_email` UNIQUE (`email`),
    CONSTRAINT `fk_users_native_language_id` FOREIGN KEY (`native_language_id`) REFERENCES `languages` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_users_target_language_id` FOREIGN KEY (`target_language_id`) REFERENCES `languages` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_user_exam` FOREIGN KEY (`current_exam_type_id`) REFERENCES `exam_types` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_user_level` FOREIGN KEY (`current_level_id`) REFERENCES `proficiency_levels` (`id`) ON DELETE SET NULL,
    CONSTRAINT `chk_users_status` CHECK (`status` IN ('PENDING', 'ACTIVE', 'SUSPENDED', 'DEACTIVATED')),
    CONSTRAINT `chk_users_daily_goal_cards` CHECK (`daily_goal_cards` BETWEEN 1 AND 1000),
    CONSTRAINT `chk_users_xp_total` CHECK (`xp_total` >= 0),
    CONSTRAINT `chk_users_streak_current` CHECK (`streak_current` >= 0),
    CONSTRAINT `chk_users_streak_longest` CHECK (`streak_longest` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_users_status_deleted` ON `users` (`status`, `deleted_at`);

