-- 10. Monetization: payments
-- (Altered in V26 for SePay: payment_code, nullable provider_transaction_id, expires_at)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `payments`;
CREATE TABLE `payments` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `user_id` BIGINT NOT NULL,
    `subscription_id` BIGINT NULL,
    `provider` VARCHAR(50) NOT NULL,
    `provider_transaction_id` VARCHAR(190) NULL,
    `payment_code` VARCHAR(50) NULL,
    `amount` DECIMAL(12,2) NOT NULL,
    `currency_code` CHAR(3) NOT NULL DEFAULT 'VND',
    `status` VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    `paid_at` DATETIME(6) NULL,
    `failed_at` DATETIME(6) NULL,
    `refunded_at` DATETIME(6) NULL,
    `expires_at` DATETIME(6) NULL,
    `failure_reason` VARCHAR(500) NULL,
    `provider_payload` JSON NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_payments` PRIMARY KEY (`id`),
    CONSTRAINT `uk_payments_provider_transaction` UNIQUE (`provider`, `provider_transaction_id`),
    CONSTRAINT `uk_payments_payment_code` UNIQUE (`payment_code`),
    CONSTRAINT `uk_provider_transaction` UNIQUE (`provider_transaction_id`),
    CONSTRAINT `fk_payments_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_payments_subscription_id` FOREIGN KEY (`subscription_id`) REFERENCES `user_subscriptions` (`id`) ON DELETE SET NULL,
    CONSTRAINT `chk_payments_amount` CHECK (`amount` >= 0),
    CONSTRAINT `chk_payments_status` CHECK (`status` IN ('PENDING', 'SUCCEEDED', 'FAILED', 'REFUNDED', 'CANCELLED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_payments_user_created` ON `payments` (`user_id`, `created_at`);
CREATE INDEX `idx_payments_status` ON `payments` (`status`);

