    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_decks` PRIMARY KEY (`id`),
    CONSTRAINT `uk_decks_deck_code` UNIQUE (`deck_code`),
    CONSTRAINT `uk_decks_slug` UNIQUE (`slug`),
    CONSTRAINT `fk_decks_owner_id` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_decks_language_id` FOREIGN KEY (`language_id`) REFERENCES `languages` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_decks_topic` FOREIGN KEY (`topic_id`) REFERENCES `topics` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_deck_exam` FOREIGN KEY (`exam_type_id`) REFERENCES `exam_types` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_deck_level` FOREIGN KEY (`level_id`) REFERENCES `proficiency_levels` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_decks_reviewed_by` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
    CONSTRAINT `chk_decks_difficulty` CHECK (`difficulty` IN ('BEGINNER', 'INTERMEDIATE', 'ADVANCED')),
    CONSTRAINT `chk_decks_visibility` CHECK (`visibility` IN ('PUBLIC', 'UNLISTED', 'PRIVATE')),
    CONSTRAINT `chk_decks_status` CHECK (`status` IN ('DRAFT', 'PENDING_REVIEW', 'PUBLISHED', 'REJECTED', 'ARCHIVED')),
    CONSTRAINT `chk_decks_counters` CHECK (`total_cards` >= 0 AND `view_count` >= 0 AND `enrollment_count` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

