DROP TABLE IF EXISTS `deck_enrollments`;
CREATE TABLE `deck_enrollments` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `user_id` BIGINT NOT NULL,
    `deck_id` BIGINT NOT NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    `max_new_cards_per_day` INT NOT NULL DEFAULT 20,
    `max_reviews_per_day` INT NOT NULL DEFAULT 100,
    `enrolled_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `paused_at` DATETIME(6) NULL,
    `completed_at` DATETIME(6) NULL,
    `dropped_at` DATETIME(6) NULL,
    `last_studied_at` DATETIME(6) NULL,
    `next_review_at` DATETIME(6) NULL,
    `mastered_cards` INT NOT NULL DEFAULT 0,
    `note` VARCHAR(500) NULL,
    `version` BIGINT NOT NULL DEFAULT 0,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_deck_enrollments` PRIMARY KEY (`id`),
    CONSTRAINT `uk_deck_enrollments_user_deck` UNIQUE (`user_id`, `deck_id`),
    CONSTRAINT `fk_deck_enrollments_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_deck_enrollments_deck_id` FOREIGN KEY (`deck_id`) REFERENCES `decks` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `chk_deck_enrollments_status` CHECK (`status` IN ('ACTIVE', 'PAUSED', 'COMPLETED', 'DROPPED')),
    CONSTRAINT `chk_deck_enrollments_mastered_cards` CHECK (`mastered_cards` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_deck_enrollments_user_status_due` ON `deck_enrollments` (`user_id`, `status`, `next_review_at`);
CREATE INDEX `idx_deck_enrollments_deck_status` ON `deck_enrollments` (`deck_id`, `status`);

-- -----------------------------------------------------------------------------
-- 18. SRS Algorithm: card_progress
-- (Altered in V2: last_rating INT NULL)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `card_progress`;
CREATE TABLE `card_progress` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `user_id` BIGINT NOT NULL,
    `card_id` BIGINT NOT NULL,
    `state` VARCHAR(20) NOT NULL DEFAULT 'NEW',
    `step` INT NOT NULL DEFAULT 0,
    `stability` DECIMAL(8,4) NOT NULL DEFAULT 0.0000,
    `difficulty` DECIMAL(8,4) NOT NULL DEFAULT 0.0000,
    `interval_days` INT NOT NULL DEFAULT 0,
    `due_at` DATETIME(6) NOT NULL,
    `last_reviewed_at` DATETIME(6) NULL,
    `reps` INT NOT NULL DEFAULT 0,
    `lapses` INT NOT NULL DEFAULT 0,
    `elapsed_days` INT NOT NULL DEFAULT 0,
    `scheduled_days` INT NOT NULL DEFAULT 0,
    `last_rating` INT NULL,
    `version` BIGINT NOT NULL DEFAULT 0,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_card_progress` PRIMARY KEY (`id`),
    CONSTRAINT `uk_card_progress_user_card` UNIQUE (`user_id`, `card_id`),
    CONSTRAINT `fk_card_progress_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_card_progress_card_id` FOREIGN KEY (`card_id`) REFERENCES `flashcards` (`id`) ON DELETE CASCADE,
    CONSTRAINT `chk_card_progress_state` CHECK (`state` IN ('NEW', 'LEARNING', 'REVIEW', 'RELEARNING')),
    CONSTRAINT `chk_card_progress_step` CHECK (`step` >= 0),
    CONSTRAINT `chk_card_progress_stability` CHECK (`stability` >= 0),
    CONSTRAINT `chk_card_progress_difficulty` CHECK (`difficulty` >= 0),
    CONSTRAINT `chk_card_progress_interval_days` CHECK (`interval_days` >= 0),
    CONSTRAINT `chk_card_progress_reps` CHECK (`reps` >= 0),
    CONSTRAINT `chk_card_progress_lapses` CHECK (`lapses` >= 0),
    CONSTRAINT `chk_card_progress_elapsed_days` CHECK (`elapsed_days` >= 0),
    CONSTRAINT `chk_card_progress_scheduled_days` CHECK (`scheduled_days` >= 0),
    CONSTRAINT `chk_card_progress_last_rating` CHECK (`last_rating` IS NULL OR `last_rating` BETWEEN 1 AND 4)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_card_progress_user_due` ON `card_progress` (`user_id`, `due_at`);
CREATE INDEX `idx_card_progress_user_state_due` ON `card_progress` (`user_id`, `state`, `due_at`);
CREATE INDEX `idx_card_progress_card` ON `card_progress` (`card_id`);

-- -----------------------------------------------------------------------------
-- 19. Learning & Study: review_sessions
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `review_sessions`;
CREATE TABLE `review_sessions` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `public_id` CHAR(36) NOT NULL,
    `user_id` BIGINT NOT NULL,
    `deck_id` BIGINT NOT NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    `mode` VARCHAR(30) NOT NULL DEFAULT 'NORMAL',
    `started_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `completed_at` DATETIME(6) NULL,
    `abandoned_at` DATETIME(6) NULL,
    `cards_studied` INT NOT NULL DEFAULT 0,
    `cards_remembered` INT NOT NULL DEFAULT 0,
    `cards_forgotten` INT NOT NULL DEFAULT 0,
    `time_spent_seconds` INT NOT NULL DEFAULT 0,
    `xp_earned` INT NOT NULL DEFAULT 0,
    `version` BIGINT NOT NULL DEFAULT 0,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_review_sessions` PRIMARY KEY (`id`),
    CONSTRAINT `uk_review_sessions_public_id` UNIQUE (`public_id`),
    CONSTRAINT `fk_review_sessions_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_review_sessions_deck_id` FOREIGN KEY (`deck_id`) REFERENCES `decks` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `chk_review_sessions_status` CHECK (`status` IN ('ACTIVE', 'COMPLETED', 'ABANDONED')),
    CONSTRAINT `chk_review_sessions_mode` CHECK (`mode` IN ('NORMAL', 'CRAM', 'CUSTOM', 'SPEED_REVIEW')),
    CONSTRAINT `chk_review_sessions_counters` CHECK (
        `cards_studied` >= 0
        AND `cards_remembered` >= 0
        AND `cards_forgotten` >= 0
        AND `time_spent_seconds` >= 0
        AND `xp_earned` >= 0
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_review_sessions_user_status_started` ON `review_sessions` (`user_id`, `status`, `started_at`);
CREATE INDEX `idx_review_sessions_deck_started` ON `review_sessions` (`deck_id`, `started_at`);

-- -----------------------------------------------------------------------------
-- 20. SRS Algorithm: srs_reviews
-- (Altered in V17: review_session_id BIGINT NULL)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `srs_reviews`;
CREATE TABLE `srs_reviews` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `client_event_id` VARCHAR(100) NOT NULL,
    `review_session_id` BIGINT NULL,
    `user_id` BIGINT NOT NULL,
    `card_id` BIGINT NOT NULL,
    `rating` INT NOT NULL,
    `response_time_ms` INT NULL,
    `state_before` VARCHAR(20) NOT NULL,
    `state_after` VARCHAR(20) NOT NULL,
    `stability_before` DECIMAL(8,4) NOT NULL,
    `stability_after` DECIMAL(8,4) NOT NULL,
    `difficulty_before` DECIMAL(8,4) NOT NULL,
    `difficulty_after` DECIMAL(8,4) NOT NULL,
    `interval_days_before` INT NOT NULL,
    `interval_days_after` INT NOT NULL,
    `due_at_before` DATETIME(6) NOT NULL,
    `due_at_after` DATETIME(6) NOT NULL,
    `xp_awarded` INT NOT NULL DEFAULT 0,
    `reviewed_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_srs_reviews` PRIMARY KEY (`id`),
    CONSTRAINT `uk_srs_reviews_client_event_id` UNIQUE (`client_event_id`),
    CONSTRAINT `fk_srs_reviews_review_session_id` FOREIGN KEY (`review_session_id`) REFERENCES `review_sessions` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_srs_reviews_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_srs_reviews_card_id` FOREIGN KEY (`card_id`) REFERENCES `flashcards` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `chk_srs_reviews_rating` CHECK (`rating` BETWEEN 1 AND 4),
    CONSTRAINT `chk_srs_reviews_response_ms` CHECK (`response_time_ms` IS NULL OR `response_time_ms` >= 0),
    CONSTRAINT `chk_srs_reviews_states` CHECK (
        `state_before` IN ('NEW', 'LEARNING', 'REVIEW', 'RELEARNING')
        AND `state_after` IN ('NEW', 'LEARNING', 'REVIEW', 'RELEARNING')
    ),
    CONSTRAINT `chk_srs_reviews_intervals` CHECK (`interval_days_before` >= 0 AND `interval_days_after` >= 0),
    CONSTRAINT `chk_srs_reviews_xp` CHECK (`xp_awarded` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_srs_reviews_user_reviewed` ON `srs_reviews` (`user_id`, `reviewed_at`);
CREATE INDEX `idx_srs_reviews_card_reviewed` ON `srs_reviews` (`card_id`, `reviewed_at`);
CREATE INDEX `idx_srs_reviews_session` ON `srs_reviews` (`review_session_id`, `reviewed_at`);

-- -----------------------------------------------------------------------------
-- 21. Assessment: quizzes
-- (Altered in V27: quiz_category, exam_type_id, level_id, deck_id nullable; V43: difficulty)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `quizzes`;
CREATE TABLE `quizzes` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `deck_id` BIGINT NULL,
    `exam_type_id` BIGINT NULL,
    `level_id` BIGINT NULL,
    `difficulty` VARCHAR(20) NULL,
    `quiz_category` VARCHAR(30) DEFAULT 'NORMAL',
    `quiz_code` VARCHAR(50) NOT NULL,
    `title` VARCHAR(200) NOT NULL,
    `description` TEXT NULL,
    `quiz_type` VARCHAR(30) NOT NULL DEFAULT 'MULTIPLE_CHOICE',
    `time_limit_seconds` INT NULL,
    `pass_score` DECIMAL(5,2) NOT NULL DEFAULT 60.00,
    `max_attempts` INT NOT NULL DEFAULT 3,
    `shuffle_questions` BOOLEAN NOT NULL DEFAULT TRUE,
    `shuffle_options` BOOLEAN NOT NULL DEFAULT TRUE,
    `total_questions` INT NOT NULL DEFAULT 0,
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_by` BIGINT NOT NULL,
    `updated_by` BIGINT NULL,
    `deleted_at` DATETIME(6) NULL,
    `version` BIGINT NOT NULL DEFAULT 0,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_quizzes` PRIMARY KEY (`id`),
    CONSTRAINT `uk_quizzes_quiz_code` UNIQUE (`quiz_code`),
    CONSTRAINT `fk_quizzes_deck_id` FOREIGN KEY (`deck_id`) REFERENCES `decks` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_quiz_exam` FOREIGN KEY (`exam_type_id`) REFERENCES `exam_types` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_quiz_level` FOREIGN KEY (`level_id`) REFERENCES `proficiency_levels` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_quizzes_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_quizzes_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
    CONSTRAINT `chk_quizzes_quiz_type` CHECK (`quiz_type` IN ('MULTIPLE_CHOICE', 'TRUE_FALSE', 'FILL_BLANK', 'MIXED')),
    CONSTRAINT `chk_quizzes_time_limit` CHECK (`time_limit_seconds` IS NULL OR `time_limit_seconds` > 0),
    CONSTRAINT `chk_quizzes_pass_score` CHECK (`pass_score` BETWEEN 0 AND 100),
    CONSTRAINT `chk_quizzes_max_attempts` CHECK (`max_attempts` = -1 OR `max_attempts` > 0),
    CONSTRAINT `chk_quizzes_total_questions` CHECK (`total_questions` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_quizzes_deck_active_deleted` ON `quizzes` (`deck_id`, `is_active`, `deleted_at`);
CREATE INDEX `idx_quizzes_cat_lvl_active` ON `quizzes` (`quiz_category`, `level_id`, `is_active`);

-- -----------------------------------------------------------------------------
-- 22. Assessment: quiz_questions
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `quiz_questions`;
CREATE TABLE `quiz_questions` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `quiz_id` BIGINT NOT NULL,
    `question_text` TEXT NOT NULL,
    `question_type` VARCHAR(30) NOT NULL DEFAULT 'MULTIPLE_CHOICE',
    `explanation` TEXT NULL,
    `points` INT NOT NULL DEFAULT 1,
    `display_order` INT NOT NULL DEFAULT 0,
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_quiz_questions` PRIMARY KEY (`id`),
    CONSTRAINT `fk_quiz_questions_quiz_id` FOREIGN KEY (`quiz_id`) REFERENCES `quizzes` (`id`) ON DELETE CASCADE,
    CONSTRAINT `chk_quiz_questions_type` CHECK (`question_type` IN ('MULTIPLE_CHOICE', 'TRUE_FALSE', 'FILL_BLANK')),
    CONSTRAINT `chk_quiz_questions_points` CHECK (`points` > 0),
    CONSTRAINT `chk_quiz_questions_order` CHECK (`display_order` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_quiz_questions_quiz_active_order` ON `quiz_questions` (`quiz_id`, `is_active`, `display_order`);

-- -----------------------------------------------------------------------------
-- 23. Assessment: quiz_question_options
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `quiz_question_options`;
CREATE TABLE `quiz_question_options` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `question_id` BIGINT NOT NULL,
    `option_text` TEXT NOT NULL,
    `is_correct` BOOLEAN NOT NULL DEFAULT FALSE,
    `display_order` INT NOT NULL DEFAULT 0,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_quiz_question_options` PRIMARY KEY (`id`),
    CONSTRAINT `fk_quiz_question_options_question_id` FOREIGN KEY (`question_id`) REFERENCES `quiz_questions` (`id`) ON DELETE CASCADE,
    CONSTRAINT `chk_quiz_question_options_order` CHECK (`display_order` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_quiz_question_options_question_order` ON `quiz_question_options` (`question_id`, `display_order`);

-- -----------------------------------------------------------------------------
-- 24. Assessment: quiz_attempts
-- (Altered in V29: level_id_at_attempt; V42: cycle_number)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `quiz_attempts`;
CREATE TABLE `quiz_attempts` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `public_id` CHAR(36) NOT NULL,
    `quiz_id` BIGINT NOT NULL,
    `user_id` BIGINT NOT NULL,
    `level_id_at_attempt` BIGINT NULL,
    `cycle_number` INT NOT NULL DEFAULT 1,
    `attempt_number` INT NOT NULL,
    `start_idempotency_key` VARCHAR(190) NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'IN_PROGRESS',
    `started_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `expires_at` DATETIME(6) NULL,
    `submitted_at` DATETIME(6) NULL,
    `abandoned_at` DATETIME(6) NULL,
    `time_spent_seconds` INT NULL,
    `total_questions` INT NOT NULL DEFAULT 0,
    `correct_answers` INT NOT NULL DEFAULT 0,
    `score_points` INT NOT NULL DEFAULT 0,
    `score_percent` DECIMAL(5,2) NULL,
    `passed` BOOLEAN NULL,
    `xp_awarded` INT NOT NULL DEFAULT 0,
    `version` BIGINT NOT NULL DEFAULT 0,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_quiz_attempts` PRIMARY KEY (`id`),
    CONSTRAINT `uk_quiz_attempts_public_id` UNIQUE (`public_id`),
    CONSTRAINT `uk_quiz_attempts_quiz_user_number` UNIQUE (`quiz_id`, `user_id`, `attempt_number`),
    CONSTRAINT `uk_quiz_attempts_start_idempotency` UNIQUE (`start_idempotency_key`),
    CONSTRAINT `fk_quiz_attempts_quiz_id` FOREIGN KEY (`quiz_id`) REFERENCES `quizzes` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_quiz_attempts_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_quiz_attempts_level` FOREIGN KEY (`level_id_at_attempt`) REFERENCES `proficiency_levels` (`id`) ON DELETE SET NULL,
    CONSTRAINT `chk_quiz_attempts_attempt_number` CHECK (`attempt_number` > 0),
    CONSTRAINT `chk_quiz_attempts_status` CHECK (`status` IN ('IN_PROGRESS', 'SUBMITTED', 'EXPIRED', 'ABANDONED')),
    CONSTRAINT `chk_quiz_attempts_score_percent` CHECK (`score_percent` IS NULL OR `score_percent` BETWEEN 0 AND 100),
    CONSTRAINT `chk_quiz_attempts_counts` CHECK (
        `total_questions` >= 0
        AND `correct_answers` >= 0
        AND `score_points` >= 0
        AND `xp_awarded` >= 0
        AND (`time_spent_seconds` IS NULL OR `time_spent_seconds` >= 0)
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_quiz_attempts_user_quiz_status` ON `quiz_attempts` (`user_id`, `quiz_id`, `status`);
CREATE INDEX `idx_quiz_attempts_quiz_submitted` ON `quiz_attempts` (`quiz_id`, `submitted_at`);

-- -----------------------------------------------------------------------------
-- 25. Assessment: quiz_attempt_questions
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `quiz_attempt_questions`;
CREATE TABLE `quiz_attempt_questions` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `attempt_id` BIGINT NOT NULL,
    `question_id` BIGINT NOT NULL,
    `display_order` INT NOT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_quiz_attempt_questions` PRIMARY KEY (`id`),
    CONSTRAINT `uk_quiz_attempt_questions_attempt_order` UNIQUE (`attempt_id`, `display_order`),
    CONSTRAINT `fk_quiz_attempt_questions_attempt_id` FOREIGN KEY (`attempt_id`) REFERENCES `quiz_attempts` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_quiz_attempt_questions_question_id` FOREIGN KEY (`question_id`) REFERENCES `quiz_questions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `chk_quiz_attempt_questions_order` CHECK (`display_order` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_quiz_attempt_questions_attempt` ON `quiz_attempt_questions` (`attempt_id`, `display_order`);

-- -----------------------------------------------------------------------------
-- 26. Assessment: quiz_attempt_options
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `quiz_attempt_options`;
CREATE TABLE `quiz_attempt_options` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `attempt_question_id` BIGINT NOT NULL,
    `option_id` BIGINT NOT NULL,
    `display_order` INT NOT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_quiz_attempt_options` PRIMARY KEY (`id`),
    CONSTRAINT `uk_quiz_attempt_options_question_order` UNIQUE (`attempt_question_id`, `display_order`),
    CONSTRAINT `fk_quiz_attempt_options_question_id` FOREIGN KEY (`attempt_question_id`) REFERENCES `quiz_attempt_questions` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_quiz_attempt_options_option_id` FOREIGN KEY (`option_id`) REFERENCES `quiz_question_options` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `chk_quiz_attempt_options_order` CHECK (`display_order` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 27. Assessment: quiz_answers
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `quiz_answers`;
CREATE TABLE `quiz_answers` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `attempt_id` BIGINT NOT NULL,
    `question_id` BIGINT NOT NULL,
    `selected_option_id` BIGINT NULL,
    `text_answer` TEXT NULL,
    `is_correct` BOOLEAN NOT NULL DEFAULT FALSE,
    `points_awarded` INT NOT NULL DEFAULT 0,
    `answered_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_quiz_answers` PRIMARY KEY (`id`),
    CONSTRAINT `uk_quiz_answers_attempt_question` UNIQUE (`attempt_id`, `question_id`),
    CONSTRAINT `fk_quiz_answers_attempt_id` FOREIGN KEY (`attempt_id`) REFERENCES `quiz_attempts` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_quiz_answers_question_id` FOREIGN KEY (`question_id`) REFERENCES `quiz_questions` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_quiz_answers_selected_option_id` FOREIGN KEY (`selected_option_id`) REFERENCES `quiz_question_options` (`id`) ON DELETE SET NULL,
    CONSTRAINT `chk_quiz_answers_points` CHECK (`points_awarded` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_quiz_answers_attempt` ON `quiz_answers` (`attempt_id`);

-- -----------------------------------------------------------------------------
-- 28. Gamification & Analytics: daily_learning_activities
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `daily_learning_activities`;
CREATE TABLE `daily_learning_activities` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `user_id` BIGINT NOT NULL,
    `activity_date` DATE NOT NULL,
    `cards_studied` INT NOT NULL DEFAULT 0,
    `cards_reviewed` INT NOT NULL DEFAULT 0,
    `quizzes_taken` INT NOT NULL DEFAULT 0,
    `time_spent_seconds` INT NOT NULL DEFAULT 0,
    `xp_earned` INT NOT NULL DEFAULT 0,
    `streak_day` INT NOT NULL DEFAULT 0,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_daily_learning_activities` PRIMARY KEY (`id`),
    CONSTRAINT `uk_daily_learning_activities_user_date` UNIQUE (`user_id`, `activity_date`),
    CONSTRAINT `fk_daily_learning_activities_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `chk_daily_learning_activities_counters` CHECK (
        `cards_studied` >= 0
        AND `cards_reviewed` >= 0
        AND `quizzes_taken` >= 0
        AND `time_spent_seconds` >= 0
        AND `xp_earned` >= 0
        AND `streak_day` >= 0
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_daily_learning_activities_user_date` ON `daily_learning_activities` (`user_id`, `activity_date`);

-- -----------------------------------------------------------------------------
-- 29. Gamification: daily_user_goals
-- (Created in V30)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `daily_user_goals`;
CREATE TABLE `daily_user_goals` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `user_id` BIGINT NOT NULL,
    `goal_date` DATE NOT NULL,
    `target_cards` INT NOT NULL,
    `confirmed` BOOLEAN NOT NULL DEFAULT FALSE,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `pk_daily_user_goals` PRIMARY KEY (`id`),
    CONSTRAINT `fk_daily_goal_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `uk_daily_goal_user_date` UNIQUE (`user_id`, `goal_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 30. Notifications: notifications
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `user_id` BIGINT NOT NULL,
    `notification_type` VARCHAR(50) NOT NULL,
    `title` VARCHAR(200) NOT NULL,
    `message` TEXT NOT NULL,
    `target_url` VARCHAR(500) NULL,
    `metadata_payload` JSON NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    `is_read` BOOLEAN NOT NULL DEFAULT FALSE,
    `read_at` DATETIME(6) NULL,
    `scheduled_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `sent_at` DATETIME(6) NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_notifications` PRIMARY KEY (`id`),
    CONSTRAINT `fk_notifications_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `chk_notifications_status` CHECK (`status` IN ('PENDING', 'SENT', 'FAILED', 'CANCELLED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_notifications_user_read_created` ON `notifications` (`user_id`, `is_read`, `created_at`);
CREATE INDEX `idx_notifications_status_scheduled` ON `notifications` (`status`, `scheduled_at`);

-- -----------------------------------------------------------------------------
-- 31. Gamification: leaderboard_snapshots
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `leaderboard_snapshots`;
CREATE TABLE `leaderboard_snapshots` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `user_id` BIGINT NOT NULL,
    `period_type` VARCHAR(20) NOT NULL,
    `period_start` DATE NOT NULL,
    `period_end` DATE NOT NULL,
    `rank_position` INT NOT NULL,
    `xp_score` BIGINT NOT NULL DEFAULT 0,
    `total_score` BIGINT NOT NULL DEFAULT 0,
    `snapshot_metadata` JSON NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_leaderboard_snapshots` PRIMARY KEY (`id`),
    CONSTRAINT `uk_leaderboard_snapshots_user_period` UNIQUE (`user_id`, `period_type`, `period_start`),
    CONSTRAINT `fk_leaderboard_snapshots_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `chk_leaderboard_snapshots_period_type` CHECK (`period_type` IN ('DAILY', 'WEEKLY', 'MONTHLY', 'ALL_TIME')),
    CONSTRAINT `chk_leaderboard_snapshots_rank` CHECK (`rank_position` > 0),
    CONSTRAINT `chk_leaderboard_snapshots_scores` CHECK (`xp_score` >= 0 AND `total_score` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_leaderboard_period_xp` ON `leaderboard_snapshots` (`period_type`, `period_start`, `xp_score` DESC);
CREATE INDEX `idx_leaderboard_period_total` ON `leaderboard_snapshots` (`period_type`, `period_start`, `total_score` DESC);

-- -----------------------------------------------------------------------------
-- 32. Gamification: achievements
-- (Created in V12; altered in V44 category, is_active, uk_achievements_code)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `achievements`;
CREATE TABLE `achievements` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `code` VARCHAR(100) NOT NULL,
    `title` VARCHAR(200) NOT NULL,
    `description` VARCHAR(500) NULL,
    `icon_url` VARCHAR(200) NULL,
    `xp_reward` INT NOT NULL,
    `condition_type` VARCHAR(50) NULL,
    `condition_value` INT NULL,
    `category` VARCHAR(50) NULL,
    `is_active` TINYINT(1) NOT NULL DEFAULT 1,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_achievements` PRIMARY KEY (`id`),
    CONSTRAINT `uk_achievements_code` UNIQUE (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 33. Gamification: user_achievements
-- (Created in V12; altered in V44 uk_user_achievement)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `user_achievements`;
CREATE TABLE `user_achievements` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `user_id` BIGINT NOT NULL,
    `achievement_id` BIGINT NOT NULL,
    `unlocked_at` DATETIME(6) NOT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_user_achievements` PRIMARY KEY (`id`),
    CONSTRAINT `uk_user_achievements` UNIQUE (`user_id`, `achievement_id`),
    CONSTRAINT `uk_user_achievement` UNIQUE (`user_id`, `achievement_id`),
    CONSTRAINT `fk_user_achievements_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_user_achievements_achievement` FOREIGN KEY (`achievement_id`) REFERENCES `achievements` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 34. Support & Chat: chat_conversations
