DROP TABLE IF EXISTS `chat_conversations`;
CREATE TABLE `chat_conversations` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `guest_token` VARCHAR(255) NULL,
    `guest_name` VARCHAR(100) NULL,
    `guest_email` VARCHAR(100) NULL,
    `guest_phone` VARCHAR(20) NULL,
    `guest_department` VARCHAR(100) NULL,
    `user_id` BIGINT NULL,
    `assigned_admin_id` BIGINT NULL,
    `status` VARCHAR(20) NOT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `pk_chat_conversations` PRIMARY KEY (`id`),
    CONSTRAINT `uk_chat_conversations_guest_token` UNIQUE (`guest_token`),
    CONSTRAINT `fk_chat_conversations_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_chat_conversations_admin` FOREIGN KEY (`assigned_admin_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 35. Support & Chat: chat_messages
-- (Created in V25)
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `chat_messages`;
CREATE TABLE `chat_messages` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `conversation_id` BIGINT NOT NULL,
    `sender_type` VARCHAR(20) NOT NULL,
    `sender_id` BIGINT NULL,
    `content` TEXT NOT NULL,
    `is_read` BOOLEAN DEFAULT FALSE,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT `pk_chat_messages` PRIMARY KEY (`id`),
    CONSTRAINT `fk_chat_messages_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `chat_conversations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------------------------------------------------------
-- 36. System & Observability: audit_logs
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `audit_logs`;
CREATE TABLE `audit_logs` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `actor_user_id` BIGINT NULL,
    `entity_type` VARCHAR(100) NOT NULL,
    `entity_id` VARCHAR(100) NOT NULL,
    `action` VARCHAR(50) NOT NULL,
    `old_state` JSON NULL,
    `new_state` JSON NULL,
    `ip_address` VARCHAR(45) NULL,
    `user_agent` VARCHAR(500) NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_audit_logs` PRIMARY KEY (`id`),
    CONSTRAINT `fk_audit_logs_actor_id` FOREIGN KEY (`actor_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_audit_logs_entity_created` ON `audit_logs` (`entity_type`, `entity_id`, `created_at`);
CREATE INDEX `idx_audit_logs_actor_created` ON `audit_logs` (`actor_user_id`, `created_at`);

-- -----------------------------------------------------------------------------
-- 37. System & Resilience: idempotency_records
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `idempotency_records`;
CREATE TABLE `idempotency_records` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `idempotency_key` VARCHAR(190) NOT NULL,
    `scope` VARCHAR(100) NOT NULL,
    `user_id` BIGINT NULL,
    `request_hash` VARCHAR(64) NOT NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'PROCESSING',
    `response_code` INT NULL,
    `response_payload` JSON NULL,
    `expires_at` DATETIME(6) NOT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_idempotency_records` PRIMARY KEY (`id`),
    CONSTRAINT `uk_idempotency_records_key_scope` UNIQUE (`idempotency_key`, `scope`),
    CONSTRAINT `fk_idempotency_records_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
    CONSTRAINT `chk_idempotency_records_status` CHECK (`status` IN ('PROCESSING', 'COMPLETED', 'FAILED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_idempotency_records_expiration` ON `idempotency_records` (`expires_at`);

-- -----------------------------------------------------------------------------
-- 38. System & Event Streaming: outbox_events
-- -----------------------------------------------------------------------------
DROP TABLE IF EXISTS `outbox_events`;
CREATE TABLE `outbox_events` (
    `id` BIGINT NOT NULL AUTO_INCREMENT,
    `aggregate_type` VARCHAR(100) NOT NULL,
    `aggregate_id` VARCHAR(100) NOT NULL,
    `event_type` VARCHAR(100) NOT NULL,
    `event_payload` JSON NOT NULL,
    `status` VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    `retry_count` INT NOT NULL DEFAULT 0,
    `max_retries` INT NOT NULL DEFAULT 5,
    `available_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `sent_at` DATETIME(6) NULL,
    `failed_at` DATETIME(6) NULL,
    `last_error` TEXT NULL,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT `pk_outbox_events` PRIMARY KEY (`id`),
    CONSTRAINT `chk_outbox_events_status` CHECK (`status` IN ('PENDING', 'PROCESSING', 'SENT', 'DEAD_LETTER')),
    CONSTRAINT `chk_outbox_events_retries` CHECK (`retry_count` >= 0 AND `max_retries` >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX `idx_outbox_events_status_available` ON `outbox_events` (`status`, `available_at`);

SET FOREIGN_KEY_CHECKS = 1;

